class SecureHandler {
public:
    Response execute(const Request& r) {           // NVI: the only way in
        if (!authn(r) || !authz(r) || !valid(r)) return deny(r);
        audit(r);
        return do_execute(r);                      // business step
    }
    virtual ~SecureHandler() = default;
protected:
    virtual Response do_execute(const Request&) = 0;
};
